100	    struct dsm_store *s = NULL;
101	    CHECK(store_open(path, &s) == STORE_OK, "open of a new file failed");
102	    CHECK(store_close(s) == STORE_OK, "close failed");
103	    CHECK(file_size() == HDR, "new file is %ld bytes, want %d", file_size(), HDR);
104	
105	    struct dsm_store_header h;
106	    memset(&h, 0, sizeof h);
107	    read_raw(&h, sizeof h);
108	    CHECK(memcmp(h.magic, DSM_STORE_MAGIC, sizeof h.magic) == 0, "magic is not DSKY");
109	    CHECK(h.schema_ver == DSM_SCHEMA_VER, "schema_ver %u", h.schema_ver);
110	    CHECK(h.record_size == REC, "record_size %u, want %d", h.record_size, REC);
111	    CHECK(h.created_real_ns > 0, "creation time was not filled in");
112	    CHECK(h.crc32 == dsm_crc32(&h, offsetof(struct dsm_store_header, crc32)),
113	          "header CRC does not match");
114	}
