130	/* Reopening must add to the end, and must not rewrite the header. */
131	static void test_reopen_appends_at_end(void)
132	{
133	    unlink(path);
134	    struct dsm_store *s = NULL;
135	    if (store_open(path, &s) != STORE_OK) {
136	        CHECK(0, "first open failed");
137	        return;
138	    }
139	    CHECK(append_range(s, 0, 3) == 0, "appends before reopen failed");
140	    store_close(s);
