157	/* A file that isn't ours is refused and left exactly as it was. */
158	static void check_refused(const void *bytes, size_t len, const char *what)
159	{
160	    write_raw(bytes, len);
161	    struct dsm_store *s = NULL;
162	    CHECK(store_open(path, &s) == STORE_ERR_FORMAT, "%s: not refused", what);
163	    CHECK(s == NULL, "%s: got a store handle anyway", what);
164	    store_close(s);
165	
166	    unsigned char back[HDR + MAX_RECS * REC];
167	    size_t n = read_raw(back, sizeof back);
168	    CHECK(n == len && memcmp(back, bytes, len) == 0, "%s: file was modified", what);
169	}
