171	static void test_foreign_files_refused(void)
172	{
173	    const char text[] = "somebody's notes file, definitely not ours\n";
174	    check_refused(text, sizeof text - 1, "text file");
175	
176	    const char shorty[] = "DSKY123456";
177	    check_refused(shorty, sizeof shorty - 1, "file shorter than a header");
178	
179	    /* A real store file with one byte of its header damaged. */
180	    unlink(path);
181	    struct dsm_store *s = NULL;
182	    if (store_open(path, &s) != STORE_OK) {
183	        CHECK(0, "open failed");
184	        return;
185	    }
186	    append_range(s, 0, 2);
187	    store_close(s);
188	    unsigned char buf[HDR + 2 * REC];
189	    size_t n = read_raw(buf, sizeof buf);
190	    CHECK(n == sizeof buf, "store file is %zu bytes, want %zu", n, sizeof buf);
191	    buf[10] ^= 0xFF;   /* inside created_real_ns */
192	    check_refused(buf, n, "damaged header");
193	}
