195	/* A header that matches what store_open() writes, with its CRC sealed. */
196	static void good_header(struct dsm_store_header *h)
197	{
198	    memset(h, 0, sizeof *h);
199	    memcpy(h->magic, DSM_STORE_MAGIC, sizeof h->magic);
200	    h->schema_ver = DSM_SCHEMA_VER;
201	    h->record_size = REC;
202	    h->created_real_ns = 1761436800000000000ull;
203	    h->crc32 = dsm_crc32(h, offsetof(struct dsm_store_header, crc32));
204	}
205	
206	/* The CRC only proves the header wasn't damaged. A header can be intact
207	 * and still wrong for us: a different kind of file, or one written by a
208	 * newer version with a different record format. Each field is checked. */
209	static void test_intact_but_wrong_header_refused(void)
210	{
211	    const size_t crc_at = offsetof(struct dsm_store_header, crc32);
212	    struct dsm_store_header h;
213	
214	    good_header(&h);
215	    write_raw(&h, sizeof h);
216	    struct dsm_store *s = NULL;
217	    CHECK(store_open(path, &s) == STORE_OK, "a correct header was refused");
218	    store_close(s);
219	
220	    good_header(&h);
221	    h.magic[3] = 'X';
222	    h.crc32 = dsm_crc32(&h, crc_at);
223	    check_refused(&h, sizeof h, "different magic");
224	
225	    good_header(&h);
226	    h.schema_ver = DSM_SCHEMA_VER + 1;
227	    h.crc32 = dsm_crc32(&h, crc_at);
228	    check_refused(&h, sizeof h, "newer schema version");
229	
230	    good_header(&h);
231	    h.record_size = REC + 16;
232	    h.crc32 = dsm_crc32(&h, crc_at);
233	    check_refused(&h, sizeof h, "different record size");
234	}
