236	/* A record whose CRC doesn't match must never reach the file. Later,
237	 * recovery cuts the file off at the first bad record, so one bad record
238	 * written now would throw away every good record written after it. */
239	static void test_bad_record_refused(void)
240	{
241	    unlink(path);
242	    struct dsm_store *s = NULL;
243	    if (store_open(path, &s) != STORE_OK) {
244	        CHECK(0, "open failed");
245	        return;
246	    }
247	    struct dsm_record r = make_rec(0);
248	    r.v[1] = 5;   /* changed after sealing */
249	    CHECK(store_append(s, &r) == STORE_ERR_BADREC, "unsealed record accepted");
250	    store_close(s);
251	    CHECK(file_size() == HDR, "file is %ld bytes; the bad record got in", file_size());
252	}
253	
254	/* Make a write really fail: lower the largest file size this process is
255	 * allowed to write (RLIMIT_FSIZE) so the third record doesn't fit. After
256	 * that, we don't know where the file ends, so every later append must be
257	 * refused, even once the limit is lifted again. */
258	static void test_failed_write_stops_appends(void)
259	{
260	    unlink(path);
261	    struct dsm_store *s = NULL;
262	    if (store_open(path, &s) != STORE_OK) {
263	        CHECK(0, "open failed");
264	        return;
265	    }
266	
267	    struct rlimit old, low;
268	    if (getrlimit(RLIMIT_FSIZE, &old) != 0) {
269	        CHECK(0, "getrlimit failed");
270	        store_close(s);
271	        return;
272	    }
273	    low = old;
274	    low.rlim_cur = HDR + 2 * REC + 10;   /* room for two records and 10 bytes */
275	
276	    /* Without this, going over the limit kills the process with SIGXFSZ
277	     * instead of returning an error from write(). */
278	    void (*old_handler)(int) = signal(SIGXFSZ, SIG_IGN);
279	    int lowered = setrlimit(RLIMIT_FSIZE, &low) == 0;
280	
281	    struct dsm_record r0 = make_rec(0), r1 = make_rec(1), r2 = make_rec(2);
282	    enum store_status a = store_append(s, &r0);
283	    enum store_status b = store_append(s, &r1);
284	    enum store_status c = store_append(s, &r2);
285	
286	    setrlimit(RLIMIT_FSIZE, &old);
287	    signal(SIGXFSZ, old_handler);
288	
289	    struct dsm_record r3 = make_rec(3);
290	    enum store_status d = store_append(s, &r3);
291	    store_close(s);
292	
293	    CHECK(lowered, "setrlimit failed, so this test proved nothing");
294	    CHECK(a == STORE_OK && b == STORE_OK, "appends under the limit failed: %d %d", a, b);
295	    CHECK(c == STORE_ERR_IO, "append over the limit returned %d, want STORE_ERR_IO", c);
296	    CHECK(d == STORE_ERR_BROKEN, "append after a failure returned %d, want STORE_ERR_BROKEN", d);
297	    long size = file_size();
298	    CHECK(size >= HDR + 2 * REC && size <= HDR + 2 * REC + 10,
299	          "file is %ld bytes, want %d..%d", size, HDR + 2 * REC, HDR + 2 * REC + 10);
300	}
301	
302	/* Add bytes to the end of the test file, the way a crash in the middle of
303	 * a write leaves them. */
304	static void append_raw(const void *buf, size_t len)
305	{
306	    FILE *f = fopen(path, "ab");
307	    CHECK(f != NULL, "could not open %s", path);
308	    if (f == NULL)
309	        return;
310	    CHECK(fwrite(buf, 1, len, f) == len, "short append to %s", path);
311	    fclose(f);
312	}
