302	/* Add bytes to the end of the test file, the way a crash in the middle of
303	 * a write leaves them. */
304	static void append_raw(const void *buf, size_t len)
305	{
306	    FILE *f = fopen(path, "ab");
307	    CHECK(f != NULL, "could not open %s", path);
308	    if (f == NULL)
309	        return;
310	    CHECK(fwrite(buf, 1, len, f) == len, "short append to %s", path);
311	    fclose(f);
312	}
313	
314	/* A fresh store file holding records 0..n-1. */
315	static void make_store(uint32_t n)
316	{
317	    unlink(path);
318	    struct dsm_store *s = NULL;
319	    if (store_open(path, &s) != STORE_OK) {
320	        CHECK(0, "open failed");
321	        return;
322	    }
323	    struct store_recovery got = store_get_recovery(s);
324	    CHECK(got.kept == 0 && got.cut_bytes == 0, "a new file reports recovery");
325	    CHECK(append_range(s, 0, n) == 0, "appends failed");
326	    store_close(s);
327	}
328	
329	/* Reopen the test file, which runs recovery, and say what it did. */
330	static struct store_recovery reopen(void)
331	{
332	    struct store_recovery got = {0, 0};
333	    struct dsm_store *s = NULL;
334	    CHECK(store_open(path, &s) == STORE_OK, "reopen failed");
335	    if (s != NULL)
336	        got = store_get_recovery(s);
337	    store_close(s);
338	    return got;
339	}
340	
341	/* A power cut in the middle of a write leaves part of a record at the end.
342	 * Reopening must cut exactly those bytes, keep every whole record, and put
343	 * the next append back on a record boundary. */
344	static void test_recover_torn_tail(void)
345	{
346	    make_store(10);
347	    unsigned char junk[20];
348	    memset(junk, 0xAB, sizeof junk);
349	    append_raw(junk, sizeof junk);
350	
351	    struct store_recovery got = reopen();
352	    CHECK(got.kept == 10, "kept %" PRIu64 ", want 10", got.kept);
353	    CHECK(got.cut_bytes == 20, "cut %" PRIu64 " bytes, want 20", got.cut_bytes);
354	    CHECK(file_size() == HDR + 10 * REC, "file is %ld bytes", file_size());
355	    check_records(10);
356	
357	    struct dsm_store *s = NULL;
358	    if (store_open(path, &s) != STORE_OK) {
359	        CHECK(0, "open after recovery failed");
360	        return;
361	    }
362	    CHECK(append_range(s, 10, 12) == 0, "appends after recovery failed");
363	    store_close(s);
364	    check_records(12);
365	}
366	
367	/* One damaged byte in record 5 of 10. Records 6-9 still pass their own
368	 * CRCs, but they are cut too. The store never writes a bad record, so a
369	 * bad one in the middle means the file was damaged after it was written,
370	 * and we can't tell how far the damage goes. The rule stays simple: keep
371	 * everything before the first bad record, nothing after it. */
372	static void test_recover_corrupt_middle(void)
373	{
374	    make_store(10);
375	    unsigned char buf[HDR + 10 * REC];
376	    size_t n = read_raw(buf, sizeof buf);
377	    CHECK(n == sizeof buf, "store file is %zu bytes, want %zu", n, sizeof buf);
378	    buf[HDR + 5 * REC + 30] ^= 0x01;   /* inside record 5's values */
379	    write_raw(buf, n);
380	
381	    struct store_recovery got = reopen();
382	    CHECK(got.kept == 5, "kept %" PRIu64 ", want 5", got.kept);
383	    CHECK(got.cut_bytes == 5 * REC, "cut %" PRIu64 " bytes, want %d",
384	          got.cut_bytes, 5 * REC);
385	    check_records(5);
386	}
387	
388	/* After a power cut, a file can end in a block of zeros: the file's size
389	 * was saved, the data never was. Zeros must never pass as a record. */
390	static void test_recover_zero_slot(void)
391	{
392	    make_store(3);
393	    unsigned char zeros[REC];
394	    memset(zeros, 0, sizeof zeros);
395	    append_raw(zeros, sizeof zeros);
396	
397	    struct store_recovery got = reopen();
398	    CHECK(got.kept == 3, "kept %" PRIu64 ", want 3", got.kept);
399	    CHECK(got.cut_bytes == REC, "cut %" PRIu64 " bytes, want %d", got.cut_bytes, REC);
400	    check_records(3);
401	}
402	
403	/* A clean file must come through recovery byte for byte unchanged. */
404	static void test_recover_clean_file_untouched(void)
405	{
406	    make_store(4);
407	    unsigned char before[HDR + 4 * REC], after[HDR + 4 * REC];
408	    size_t nb = read_raw(before, sizeof before);
409	
410	    struct store_recovery got = reopen();
411	    CHECK(got.kept == 4, "kept %" PRIu64 ", want 4", got.kept);
412	    CHECK(got.cut_bytes == 0, "cut %" PRIu64 " bytes from a clean file", got.cut_bytes);
413	    size_t na = read_raw(after, sizeof after);
414	    CHECK(na == nb && memcmp(before, after, nb) == 0, "recovery changed a clean file");
415	}
416	
417	/* A header with no records, then a header with less than one record. */
418	static void test_recover_header_only(void)
419	{
420	    make_store(0);
421	    struct store_recovery got = reopen();
422	    CHECK(got.kept == 0 && got.cut_bytes == 0, "header-only file: kept %" PRIu64
423	          ", cut %" PRIu64, got.kept, got.cut_bytes);
424	
425	    unsigned char junk[30];
426	    memset(junk, 0x5A, sizeof junk);
427	    append_raw(junk, sizeof junk);
428	    got = reopen();
429	    CHECK(got.kept == 0, "kept %" PRIu64 ", want 0", got.kept);
430	    CHECK(got.cut_bytes == 30, "cut %" PRIu64 " bytes, want 30", got.cut_bytes);
431	    CHECK(file_size() == HDR, "file is %ld bytes, want %d", file_size(), HDR);
432	}
433	
434	/* Running recovery twice does the same as running it once (lec11: undo and
435	 * redo are idempotent, because a crash can also happen during recovery). */
436	static void test_recover_idempotent(void)
437	{
438	    make_store(6);
439	    unsigned char junk[7];
440	    memset(junk, 0xEE, sizeof junk);
441	    append_raw(junk, sizeof junk);
442	
443	    struct store_recovery first = reopen();
444	    unsigned char once[HDR + 6 * REC + 8], twice[HDR + 6 * REC + 8];
445	    size_t n1 = read_raw(once, sizeof once);
446	
447	    struct store_recovery second = reopen();
448	    size_t n2 = read_raw(twice, sizeof twice);
449	
450	    CHECK(first.kept == 6 && first.cut_bytes == 7, "first recovery: kept %" PRIu64
451	          ", cut %" PRIu64, first.kept, first.cut_bytes);
452	    CHECK(second.kept == 6 && second.cut_bytes == 0, "second recovery: kept %" PRIu64
453	          ", cut %" PRIu64, second.kept, second.cut_bytes);
454	    CHECK(n1 == n2 && memcmp(once, twice, n1) == 0, "second recovery changed the file");
455	}
