#ifndef DSM_RECORD_H
#define DSM_RECORD_H

#include <stdbool.h>
#include <stddef.h>
#include <stdint.h>

#define DSM_SCHEMA_VER 1

/* Starts at 1 so a zeroed record never looks like a real kind. */
enum dsm_kind {
    DSM_KIND_SAMPLE    = 1,
    DSM_KIND_FEATURE   = 2,
    DSM_KIND_STATE     = 3,
    DSM_KIND_HEARTBEAT = 4,
    DSM_KIND_FAULT     = 5,
    DSM_KIND_START     = 6,   /* first record of every run; seq 0, v[0] = run number */
};

/* dsm_record.source_id: which process made the record. These numbers are
 * stored on disk, so they never change. 0 is never used. */
enum dsm_source {
    DSM_SRC_SKYD    = 1,   /* TSL2591, sky brightness */
    DSM_SRC_CLOUDD  = 2,   /* MLX90614, sky IR temperature */
    DSM_SRC_ENVD    = 3,   /* BME280, air temperature, humidity, pressure */
    DSM_SRC_FUSIOND = 4,
    DSM_SRC_DSKYD   = 5,
    DSM_SRC_STORED  = 6,
};

/* v[0] of a FAULT record: what went wrong. */
enum dsm_fault {
    DSM_FAULT_READ    = 1,   /* an I2C read failed; v[1] = errno */
    DSM_FAULT_CHIP_ID = 2,   /* the chip answered with the wrong ID */
};

/* Bits in dsm_record.flags. They describe the reading, not the bytes.
 * SYNTHETIC is required by the spec: replayed or made-up data has to be
 * labeled everywhere it appears, so it is part of the record itself. */
enum dsm_flag {
    DSM_FLAG_VALID       = 1u << 0,
    DSM_FLAG_STALE       = 1u << 1,
    DSM_FLAG_SYNTHETIC   = 1u << 2,
    DSM_FLAG_CALIBRATING = 1u << 3,
};

/* One record, exactly as it sits on disk. */
struct dsm_record {
    uint64_t t_mono_ns;   /* CLOCK_MONOTONIC: for measuring intervals */
    uint64_t t_real_ns;   /* CLOCK_REALTIME: the wall-clock label */
    uint16_t schema_ver;
    uint16_t source_id;   /* which process produced it */
    uint16_t kind;        /* enum dsm_kind */
    uint16_t flags;       /* enum dsm_flag bits */
    int32_t  v[4];        /* fixed-point values; meaning depends on kind */
    uint32_t seq;         /* per-source counter: a gap means lost data */
    uint32_t crc32;       /* covers every byte before this field */
};

/* We write the struct's bytes straight to disk, so its layout IS the file
 * format. If an edit changes the layout, the build stops here instead of
 * the files quietly becoming unreadable. */
_Static_assert(sizeof(struct dsm_record) == 48,
               "dsm_record must be exactly 48 bytes");
_Static_assert(offsetof(struct dsm_record, crc32) == 44,
               "crc32 must be the last 4 bytes of the record");
_Static_assert(__BYTE_ORDER__ == __ORDER_LITTLE_ENDIAN__,
               "the on-disk format assumes a little-endian host");

void record_init(struct dsm_record *r, enum dsm_kind kind, uint16_t source_id);
void record_seal(struct dsm_record *r);
bool record_intact(const struct dsm_record *r);

#endif
#include "common/record.h"
#include "common/crc32.h"

#include <string.h>

/* Zero the whole record first. Any byte left uninitialized would end up in
 * the CRC, and valgrind on the Pi reports that as a use of uninitialized
 * memory even when the result looks fine. */
void record_init(struct dsm_record *r, enum dsm_kind kind, uint16_t source_id)
{
    memset(r, 0, sizeof *r);
    r->schema_ver = DSM_SCHEMA_VER;
    r->kind = (uint16_t)kind;
    r->source_id = source_id;
}

void record_seal(struct dsm_record *r)
{
    r->crc32 = dsm_crc32(r, offsetof(struct dsm_record, crc32));
}

bool record_intact(const struct dsm_record *r)
{
    return r->crc32 == dsm_crc32(r, offsetof(struct dsm_record, crc32));
}
#ifndef DSM_LOG_H
#define DSM_LOG_H

#include <stdio.h>

/* Not LOG_*: <syslog.h> already uses those names. */
enum log_level {
    LVL_INFO,
    LVL_WARN,
    LVL_ERROR,
};

/* Call once at start. proc is the program's name. out is where lines go:
 * stderr in the daemons (journald collects it under systemd). */
void log_init(const char *proc, FILE *out);

/* Writes one line, in the format DESIGN.md promises:
 *
 *   2026-10-28T19:02:11-0600 1234.567 stored[812] WARN recover kept=118 cut_bytes=31
 *   <wall-clock time>        <mono s> <proc>[pid] LEVEL event  k=v ...
 *
 * fmt is the k=v part, printf-style, or NULL for none. A line longer than
 * the buffer is cut short but still ends with a newline. */
void log_msg(enum log_level lvl, const char *event, const char *fmt, ...)
    __attribute__((format(printf, 3, 4)));

#endif
#include "common/log.h"

#include <stdarg.h>
#include <string.h>
#include <time.h>
#include <unistd.h>

enum { LINE_MAX_BYTES = 512 };

static const char *log_proc = "?";
static FILE *log_out;          /* NULL means stderr */

void log_init(const char *proc, FILE *out)
{
    log_proc = proc;
    log_out = out;
    tzset();                   /* so localtime_r uses this machine's time zone */
}

static const char *level_name(enum log_level lvl)
{
    switch (lvl) {
    case LVL_INFO:  return "INFO";
    case LVL_WARN:  return "WARN";
    case LVL_ERROR: return "ERROR";
    }
    return "?";
}

/* Add to the line. If it doesn't fit, it is cut short. One byte is always
 * left free for the '\n'. */
static void vadd(char *line, size_t *len, const char *fmt, va_list ap)
{
    size_t room = LINE_MAX_BYTES - 1 - *len;   /* includes vsnprintf's '\0' */
    int w = vsnprintf(line + *len, room, fmt, ap);
    if (w < 0)
        return;
    *len += (size_t)w < room ? (size_t)w : room - 1;
}

static void add(char *line, size_t *len, const char *fmt, ...)
{
    va_list ap;
    va_start(ap, fmt);
    vadd(line, len, fmt, ap);
    va_end(ap);
}

void log_msg(enum log_level lvl, const char *event, const char *fmt, ...)
{
    char line[LINE_MAX_BYTES];
    size_t len = 0;
    struct timespec real = {0, 0}, mono = {0, 0};
    struct tm tm;

    clock_gettime(CLOCK_REALTIME, &real);
    clock_gettime(CLOCK_MONOTONIC, &mono);

    if (localtime_r(&real.tv_sec, &tm) != NULL)
        len = strftime(line, sizeof line - 1, "%Y-%m-%dT%H:%M:%S%z", &tm);
    if (len == 0)
        add(line, &len, "0000-00-00T00:00:00+0000");   /* time unknown */

    add(line, &len, " %lld.%03ld %s[%ld] %s %s",
        (long long)mono.tv_sec, mono.tv_nsec / 1000000L,
        log_proc, (long)getpid(), level_name(lvl), event);

    if (fmt != NULL) {
        va_list ap;
        add(line, &len, " ");
        va_start(ap, fmt);
        vadd(line, &len, fmt, ap);
        va_end(ap);
    }
    line[len++] = '\n';

    /* The whole line is built first and written with one call, so it isn't
     * split into pieces the way several fprintf calls could split it. */
    FILE *out = log_out != NULL ? log_out : stderr;
    fwrite(line, 1, len, out);
    fflush(out);
}
#ifndef DSM_STORE_CLIENT_H
#define DSM_STORE_CLIENT_H

#include "common/record.h"

#include <stdint.h>

/* The sending half of the stored protocol, used by every process that
 * produces records (the sensor programs now; fusiond and dskyd at M4).
 *
 * The protocol (docs/m3-plan.md): AF_UNIX SOCK_SEQPACKET, one sealed
 * 48-byte struct dsm_record per message, clients only send, stored never
 * replies. Linux only: macOS does not support SOCK_SEQPACKET.
 *
 * This header is the agreement between the sensor side and the storage
 * side. Change it only when both partners agree. */

/* Opaque: only store_client.c can see inside. */
struct store_client;

/* Remembers the socket path. Does not connect yet, so it works whether
 * or not stored is running. NULL only if out of memory or the path is
 * too long for a sockaddr_un (errno says which). */
struct store_client *store_client_new(const char *socket_path);

/* Sends one sealed record as one message. Never blocks: if stored is
 * down, slow or gone, the record is dropped and counted, and the caller
 * keeps sampling (the seq gap shows the loss). Reconnects on its own,
 * at most one attempt per second. Returns 0 if sent, -1 if dropped. */
int store_client_send(struct store_client *c, const struct dsm_record *r);

/* Records dropped since store_client_new(). */
uint64_t store_client_dropped(const struct store_client *c);

/* Closes the connection and frees. NULL-safe. */
void store_client_free(struct store_client *c);

#endif
