        errno = saved_errno;
        return STORE_ERR_IO;
    }
    int rc = fsync(fd);
    saved_errno = errno;
    close(fd);
    errno = saved_errno;
    return rc == 0 ? STORE_OK : STORE_ERR_IO;
}

